"""Contact sheet text for substitute teachers."""

from typing import Iterable
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _name_key(student: Student) -> str:
    return student.display_name


def _check_roster(roster: list) -> None:
    if not roster:
        raise ProjectError("no students to list")
    gaps = [item for item in roster if not item.email]
    if gaps:
        names = ", ".join(map(_name_key, gaps))
        raise ProjectError(f"no email for {names}")


def _row(item: Student, width: int, sections: int) -> str:
    return (
        f"{item.display_name:<{width}}  "
        f"{item.section:<{sections}}  {item.email}"
    )


# ---
def render_contact_sheet(
    students: Iterable[Student],
) -> str:
    """One aligned row per student, sorted by name."""
    roster = sorted(students, key=_name_key)
    _check_roster(roster)
    width = max(len(item.display_name) for item in roster)
    sections = max(len(item.section) for item in roster)
    rows = [_row(item, width, sections) for item in roster]
    return "\n".join(rows)
